 const { useState, useEffect } = React;

 function FormField({ label, id, type, value, onChange, error, required, helperText, placeholder }) {
   const describedBy = [];
   if (helperText) describedBy.push(`${id}-helper`);
   if (error) describedBy.push(`${id}-error`);

   return (
     <div className="form-field">
       <label htmlFor={id}>
         {label} {required && <span aria-hidden="true">*</span>}
         {required && <span className="sr-only">(required)</span>}
       </label>
       <input
         id={id}
         name={id}
         type={type}
         value={value}
         onChange={onChange}
         required={required}
         aria-required={required}
         aria-invalid={!!error}
         aria-describedby={describedBy.length > 0 ? describedBy.join(' ') : undefined}
         className={error ? 'invalid' : ''}
         placeholder={placeholder}
       />
       {helperText && (
         <div id={`${id}-helper`} className="helper-text">
           {helperText}
         </div>
       )}
       <div id={`${id}-error`} className="error-message" role="alert">
         {error}
       </div>
     </div>
   );
 }

 function ContactForm() {
   const [formData, setFormData] = useState({
     fullName: '',
     email: '',
     phone: ''
   });

   const [errors, setErrors] = useState({});
   const [isSubmitted, setIsSubmitted] = useState(false);

   const validate = (name, value) => {
     let error = '';
     if (name === 'fullName') {
       if (!value.trim()) error = 'Full name is required';
     } else if (name === 'email') {
       if (!value.trim()) {
         error = 'Email address is required';
       } else if (!/\S+@\S+\.\S+/.test(value)) {
         error = 'Please enter a valid email address';
       }
     } else if (name === 'phone') {
       if (value && !/^\+?[\d\s-]{7,15}$/.test(value)) {
         error = 'Please enter a valid phone number (e.g., +1 234 567 8900)';
       }
     }
     return error;
   };

   const handleChange = (e) => {
     const { name, value } = e.target;
     setFormData(prev => ({ ...prev, [name]: value }));

     // Clear error when user starts typing
     if (errors[name]) {
       setErrors(prev => ({ ...prev, [name]: '' }));
     }
   };

   const handleSubmit = (e) => {
     e.preventDefault();

     const newErrors = {};
     Object.keys(formData).forEach(key => {
       const error = validate(key, formData[key]);
       if (error) newErrors[key] = error;
     });

     setErrors(newErrors);

     if (Object.keys(newErrors).length === 0) {
       setIsSubmitted(true);
       console.log('Form submitted:', formData);
       // In a real app, you'd send data to a server here
     } else {
       // Focus the first invalid field
       const firstErrorKey = Object.keys(newErrors)[0];
       const element = document.getElementById(firstErrorKey);
       if (element) element.focus();
     }
   };

   if (isSubmitted) {
     return (
       <div className="success-message" aria-live="polite">
         <h2>Thank you!</h2>
         <p>Your message has been sent successfully. We'll get back to you soon.</p>
         <button onClick={() => setIsSubmitted(false)}>Send another message</button>
       </div>
     );
   }

   return (
     <form onSubmit={handleSubmit} noValidate>
       <h1>Contact Support</h1>

       <FormField
         label="Full Name"
         id="fullName"
         type="text"
         value={formData.fullName}
         onChange={handleChange}
         error={errors.fullName}
         required={true}
         placeholder="Jane Doe"
       />

       <FormField
         label="Email Address"
         id="email"
         type="email"
         value={formData.email}
         onChange={handleChange}
         error={errors.email}
         required={true}
         placeholder="jane@example.com"
       />

       <FormField
         label="Phone Number"
         id="phone"
         type="tel"
         value={formData.phone}
         onChange={handleChange}
         error={errors.phone}
         required={false}
         helperText="Format: +1 234 567 8900"
         placeholder="+1 234 567 8900"
       />

       <button type="submit">Submit</button>
     </form>
   );
 }

 function App() {
   return (
     <div className="container">
       <ContactForm />
     </div>
   );
 }

 const root = ReactDOM.createRoot(document.getElementById('root'));
 root.render(<App />);

